199				"{\"chainId\":\"1\",\"blockHash\":\"0x\",\"blockNumber\":1,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"GasPrice\":1,\"Index\":null}]}",
200				1, "swaps[0]", "Index",
201			},
202			{
203				"missing index on later line after blanks",
