205					"{\"chainId\":\"1\",\"blockHash\":\"0x2\",\"blockNumber\":2,\"swaps\":[{\"TxHash\":\"0x1\",\"Pool\":\"p1\",\"Trader\":\"t\",\"In\":1,\"Out\":1,\"GasPrice\":1}]}",
206				3, "swaps[0]", "Index",
207			},
