package mevwatch

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func validBlock(hash string) string {
	return `{"chainId":"1","blockHash":"` + hash + `","blockNumber":1,"swaps":[]}`
}

func TestScratchTrailingContentRejected(t *testing.T) {
	base := `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[]}`
	cases := []struct {
		name  string
		input string
		line  int
	}{
		{"extra close brace", base + "}", 1},
		{"extra close bracket", base + "]", 1},
		{"second object", base + `{"chainId":"1","blockHash":"0x2","blockNumber":2,"swaps":[]}`, 1},
		{"trailing array", base + "[]", 1},
		{"trailing string", base + `"x"`, 1},
		{"trailing number", base + "42", 1},
		{"trailing true", base + "true", 1},
		{"trailing false", base + "false", 1},
		{"trailing null", base + "null", 1},
		{"trailing comma", base + ",", 1},
		{"space then brace", base + " }", 1},
		{"tab then bracket", base + "\t]", 1},
		{"spaces then object", base + "  " + base, 1},
		{"tab then number", base + "\t7", 1},
		{"line after blanks", "\n \n" + base + "}", 3},
		{"bad second line with blanks counted", validBlock("0x1") + "\n\n" + validBlock("0x2") + " null", 3},
		{"last line no newline still rejected", validBlock("0x1") + "\n" + base + "x", 2},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			_, err := Replay(strings.NewReader(tc.input), dir)
			if err == nil {
				t.Fatal("expected rejection")
			}
			var le *LineError
			if !errors.As(err, &le) {
				t.Fatalf("error %v is not LineError", err)
			}
			if le.Line != tc.line {
				t.Fatalf("line = %d, want %d: %v", le.Line, tc.line, err)
			}
			if !strings.Contains(strings.ToLower(err.Error()), "trailing") {
				t.Fatalf("error must mention trailing content: %v", err)
			}
			if _, serr := os.Stat(filepath.Join(dir, archiveFileName)); !errors.Is(serr, os.ErrNotExist) {
				t.Fatalf("archive written after failed replay: %v", serr)
			}
		})
	}
}

func TestScratchTrailingAfterValidAndDuplicate(t *testing.T) {
	dir := t.TempDir()
	replay(t, dir, validBlock("0xarchived"))
	// New valid block, then trailing junk on a line whose block is already
	// archived: whole file must fail, no new block persisted.
	input := validBlock("0xnew") + "\n" + validBlock("0xarchived") + "}"
	if _, err := Replay(strings.NewReader(input), dir); err == nil {
		t.Fatal("duplicate block line with trailing brace must reject file")
	}
	if _, err := Query(dir, "1", "0xnew"); !errors.Is(err, ErrUnknownBlock) {
		t.Fatalf("valid earlier block leaked: %v", err)
	}
	r, err := Query(dir, "1", "0xarchived")
	if err != nil || r.BlockNumber != 1 {
		t.Fatalf("archived report damaged: %v %+v", err, r)
	}
}

func TestScratchValidInputsStillAccepted(t *testing.T) {
	dir := t.TempDir()
	input := "  " + validBlock("0x1") + "  \n" +
		"\t" + validBlock("0x2") + "\t\n" +
		"\n" +
		validBlock("0x3") // no trailing newline
	reports := replay(t, dir, input)
	if len(reports) != 3 {
		t.Fatalf("got %d reports, want 3", len(reports))
	}
}

