	path := filepath.Join(dir, "blocks.jsonl")
	good := `{"chainId":"1","blockHash":"0x1","blockNumber":1,"swaps":[]}`
	bad := `{"chainId":"1","blockHash":"0x2","blockNumber":2,"swaps":[]}}`
	os.WriteFile(path, []byte(good+"\n"+bad+"\n"), 0o644)

