		fmt.Println("ReplayFile rejected:", err)
	} else {
		fmt.Println("ReplayFile: BUG - accepted")
	}
	if _, err := mevwatch.ReplayFileWithVersion(path, dir, mevwatch.BuiltinVersionID); err != nil {
		fmt.Println("ReplayFileWithVersion rejected:", err)
	} else {
		fmt.Println("ReplayFileWithVersion: BUG - accepted")
	}
	if _, err := mevwatch.Query(dir, "1", "0x1"); err == nil {
		fmt.Println("BUG: 0x1 leaked into archive")
	} else {
		fmt.Println("archive untouched:", err)
	}
}
EOF
